SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'sektoren', 'Bereiche nach §1 (Wasserwirtschaft / Wasserbau / Abwasser / Abfall)', 'json', NULL, false, '§1', 'Plan 3: Mehrfachauswahl über die vier gedruckten Bereiche (L196) neben den vier Booleans sector_* (REQ-01 liest die Booleans weiter — Ablösung STAGED m820_3-J-1).', 'imported_unverified', 'Das Merkblatt richtet sich an Auftraggeber und Auftragnehmer (beauftragte Ingenieurbüros) für planerische Arbeiten bei der Herstellung von Anlagen in den Bereichen Wasserwirtschaft, Wasserbau, Abwasser und Abfall.', 'select_many', '{"title":"Bereiche (§1 Anwendungsbereich)","subtitle":"Wasserwirtschaft · Wasserbau · Abwasser · Abfall — Mehrfachauswahl","note":"Das Merkblatt richtet sich an Auftraggeber und Auftragnehmer (beauftragte Ingenieurbüros) für planerische Arbeiten bei der Herstellung von Anlagen in den Bereichen Wasserwirtschaft, Wasserbau, Abwasser und Abfall."}'::jsonb, NULL, NULL, '[{"value":"wasserwirtschaft","label_de":"Wasserwirtschaft","order_index":0},{"value":"wasserbau","label_de":"Wasserbau","order_index":1},{"value":"abwasser","label_de":"Abwasser","order_index":2},{"value":"abfall","label_de":"Abfall","order_index":3}]'::jsonb, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
