INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'anwendungshinweise', 'Anwendungshinweise nach §1 (vier gedruckte Hinweise)', 'json', NULL, false, '§1 Anwendungshinweise', 'Plan 3: Mehrfachauswahl über die vier gedruckten Anwendungshinweise (L200 / L202 / L204 / L206) neben den Booleans anw_hinweis_1…4_confirmed (REQ-02 hat eine leere Bedingung — Vorschlag STAGED m820_3-G-5; Ablösung der Booleans m820_3-J-1).', 'imported_unverified', 'I Im konkreten Projekt werden aus den Qualitätselementen die projektspezifischen Anforderungen und Aufgabenlisten, inklusive Zuständigkeiten, vom Anwendenden entwickelt und in Arbeitsunterlagen (beispielsweise Checklisten) dokumentiert. — 1 Es wird darauf hingewiesen, dass die bereitgestellten Qualitätselemente einzelne Anhaltspunkte für die Projektabwicklung darstellen. Eine Vervollständigung an den jeweiligen Projektaufgaben wird im Projektteam durchgeführt. — I Die Qualitätselemente unterstützen die Bearbeitenden dabei, die Leistungen, die zum Projekterfolg beitragen, auch im Austausch innerhalb des Projektteams, zu identifizieren und systematisch abzuarbeiten. — 1 Die vollständige Ablaufstruktur für Projekte aller Art ergibt sich aus der eigenverantwortlichen Anwendung und projektspezifischen Anpassung der im Merkblatt vorgelegten Hinweise.', 'select_many', '{"title":"Anwendungshinweise (§1) — zur Kenntnis genommen","subtitle":"die vier gedruckten Hinweise — Mehrfachauswahl","note":"Der neu erarbeitete Teil 3 bietet, ergänzend zu Teil 1 und Teil 2, weitere Handreichungen für die praktische Umsetzung in Projekten hin zu einer guten Qualität. Die Hinweise, die in Bezug zu einer besseren Qualität gegeben werden, sind gegliedert nach den in Teil 1 und Teil 2 bereits verwendeten Phasen. Das Erreichen der Phasenziele kann mit den in Teil 3 in den Anhängen jeweils hinterlegten Qualitätselementen überprüft werden. Dabei stellen die angegebenen Qualitätselemente nur eine projektübergeordnete Auswahl an Kriterien dar, die im Anwendungsfall projektspezifisch ausgewählt und ergänzt werden müssen. — Der vorliegende Teil 3 der Merkblattreihe DWA-M 820 „Qualität von Ingenieurleistungen optimieren“ ergänzt die Ausführungen der Teile 1 und 2 und gibt Handreichungen für die praktische Umsetzung. Die Hinweise sind gegliedert nach den in Teil 1 und Teil 2 bereits verwendeten Leistungsphasen. Das Erreichen der Phasenziele kann mit den in Teil 3 hinterlegten Qualitätselementen überprüft werden. Die in Anhang A und B angegebenen Qualitätselemente stellen eine Auswahl an Kriterien für die Projektabwicklung dar."}'::jsonb, NULL, NULL, '[{"value":"hinweis_1","label_de":"Im konkreten Projekt werden aus den Qualitätselementen die projektspezifischen Anforderungen und Aufgabenlisten, inklusive Zuständigkeiten, vom Anwendenden entwickelt und in Arbeitsunterlagen (beispielsweise Checklisten) dokumentiert.","order_index":0},{"value":"hinweis_2","label_de":"Es wird darauf hingewiesen, dass die bereitgestellten Qualitätselemente einzelne Anhaltspunkte für die Projektabwicklung darstellen. Eine Vervollständigung an den jeweiligen Projektaufgaben wird im Projektteam durchgeführt.","order_index":1},{"value":"hinweis_3","label_de":"Die Qualitätselemente unterstützen die Bearbeitenden dabei, die Leistungen, die zum Projekterfolg beitragen, auch im Austausch innerhalb des Projektteams, zu identifizieren und systematisch abzuarbeiten.","order_index":2},{"value":"hinweis_4","label_de":"Die vollständige Ablaufstruktur für Projekte aller Art ergibt sich aus der eigenverantwortlichen Anwendung und projektspezifischen Anpassung der im Merkblatt vorgelegten Hinweise.","order_index":3}]'::jsonb, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'anwendungshinweise') AND w.code = 'M8203-02' AND s.code = 'DWA-M-820-3';
