INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'qe64b_items', 'Qualitätselemente B. 3 QE 6.4: Ausführungsvorbereitung — Teil 2 (Nr. 18–50) (je Kriterium Bewertung Y / P / N / NA)', 'json', NULL, false, 'Anhang B.3 (QE 6.4)', 'Plan 3: Zeilen je gedrucktem Kriterium aus QE_B3 (33 Kriterien Nr. 18–50; Nr. → Kriterium / Hinweise aus dem Katalog, Bewertung Y / P / N / NA, Nachweis, Bemerkung); Zählungen → qe64b_items_y_calc / qe64b_items_p_calc / qe64b_items_n_calc / qe64b_items_na_calc / qe64b_items_rated (M8203-15-D1 … -D5), Anteile je Bewertung → qe64b_share_y_pct / qe64b_share_p_pct / qe64b_share_n_pct / qe64b_share_na_pct (M8203-15-D6 … -D9, Nenner qe64b_items_total); Erfüllungsgrad qe64b_fulfilment_pct bleibt Eingabe (P-Gewicht / NA-Behandlung nicht gedruckt — m820_3-F-1). Sichtbar für project_type einzelprojekt / both — wirksam erst nach m820_3-C-1.', 'imported_unverified', '\caption{B. 3 QE 6.4: Ausführungsvorbereitung} — Der neu erarbeitete Teil 3 bietet, ergänzend zu Teil 1 und Teil 2, weitere Handreichungen für die praktische Umsetzung in Projekten hin zu einer guten Qualität. Die Hinweise, die in Bezug zu einer besseren Qualität gegeben werden, sind gegliedert nach den in Teil 1 und Teil 2 bereits verwendeten Phasen. Das Erreichen der Phasenziele kann mit den in Teil 3 in den Anhängen jeweils hinterlegten Qualitätselementen überprüft werden. Dabei stellen die angegebenen Qualitätselemente nur eine projektübergeordnete Auswahl an Kriterien dar, die im Anwendungsfall projektspezifisch ausgewählt und ergänzt werden müssen. — Der vorliegende Teil 3 der Merkblattreihe DWA-M 820 „Qualität von Ingenieurleistungen optimieren“ ergänzt die Ausführungen der Teile 1 und 2 und gibt Handreichungen für die praktische Umsetzung. Die Hinweise sind gegliedert nach den in Teil 1 und Teil 2 bereits verwendeten Leistungsphasen. Das Erreichen der Phasenziele kann mit den in Teil 3 hinterlegten Qualitätselementen überprüft werden. Die in Anhang A und B angegebenen Qualitätselemente stellen eine Auswahl an Kriterien für die Projektabwicklung dar. — Die Aufteilung in „Konzept für das Gesamtsystem“ und „Projekte“ ist dabei eine elementare Grundlage. Die grundsätzlichen strategischen Überlegungen, die auch die größten Einsparungen im Lebenszyklus des Gesamtsystems bringen können, werden im „Konzept für das Gesamtsystem“ erarbeitet. Hier werden alle zusammenwirkenden Anlagenteile (beispielsweise Kläranlagen, Kanäle, — Auf der Grundlage des Konzepts für das Gesamtsystem wurden erforderliche Projekte identifiziert (siehe 5.4). Diese werden im Folgenden einzeln betrachtet und umgesetzt.', 'register', '{"title":"Qualitätselemente — QE 6.4: Ausführungsvorbereitung (Anhang B.3, Teil 2: Vorbereiten + Mitwirken bei der Vergabe — Nr. 18–50)","subtitle":"je gedrucktem Kriterium (B. 3 QE 6.4: Ausführungsvorbereitung, Nr. 18–50) eine Zeile — Bewertung Y / P / N / NA mit Nachweis; Zeilen außerhalb Teil 2 (Nr. 18–50) zählen hier nicht","add_label":"+ Kriterium","placement":"section","columns":[{"key":"nr","label":"Nr.","type":"lookup_key","required":true,"lookup":{"table_code":"QE_B3","group_by":"group_label"},"aria_label":"Kriterium aus B. 3 QE 6.4: Ausführungsvorbereitung wählen"},{"key":"kriterium","label":"Qualitätselemente/-kriterien","type":"lookup_value","lookup":{"table_code":"QE_B3","key_column":"nr","value":"kriterium"}},{"key":"hinweise","label":"Hinweise","type":"lookup_value","lookup":{"table_code":"QE_B3","key_column":"nr","value":"hinweise"}},{"key":"rating","label":"Bewertung","type":"enum","required":true,"options":["y","p","n","na"],"option_labels":{"y":"Y — erfüllt","p":"P — teilweise erfüllt","n":"N — nicht erfüllt","na":"NA — nicht zutreffend"}},{"key":"evidence","label":"Nachweis","type":"text","aria_label":"Nachweis / Beleg zum Kriterium"},{"key":"remark","label":"Bemerkung","type":"text","aria_label":"Bemerkung zum Kriterium"},{"key":"in_teil","label":"Teil 2 (Nr. 18–50)","type":"derived","expr":"if(lookup(''QE_B3'', nr, ''nr_num'') >= 18 AND lookup(''QE_B3'', nr, ''nr_num'') <= 50, 1, 0)","display":"badge","value_labels":{"0":"außerhalb Teil 2 (Nr. 18–50) — gehört auf das andere Arbeitsblatt, zählt hier nicht","1":"gehört zu Teil 2 (Nr. 18–50)"}}],"footer":["qe64b_items_rated","qe64b_items_y_calc","qe64b_items_p_calc","qe64b_items_n_calc","qe64b_items_na_calc","qe64b_share_y_pct","qe64b_share_p_pct","qe64b_share_n_pct","qe64b_share_na_pct"],"note":"Dabei stellen die angegebenen Qualitätselemente nur eine projektübergeordnete Auswahl an Kriterien dar, die im Anwendungsfall projektspezifisch ausgewählt und ergänzt werden müssen. — Die in Anhang A und B angegebenen Qualitätselemente stellen eine Auswahl an Kriterien für die Projektabwicklung dar. — Zeilen werden aus dem Katalog gewählt (Vollständigkeit: qe64b_items_rated == 33 gedruckte Kriterien); projektspezifische Ergänzungen sind nicht als Zeile erfassbar (m820_3-X-1)."}'::jsonb, NULL, 'project_type IN {''einzelprojekt'', ''both''}', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
