FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'qe66_items_rated') AND w.code = 'M8203-17' AND s.code = 'DWA-M-820-3';
